steps.codeExample:
public class Jogo {
    public required string Nome { get; init; }
    public decimal Preco { get; private set; } = 50m;
    public void DarDesconto(decimal v) => Preco -= v;
}
var j = new Jogo { Nome = "StarRunner" };
j.DarDesconto(10m);
Console.WriteLine($"{j.Nome}: R$ {j.Preco}");

